Given an array arr[] containing n positive integers,  find the length of the longest bitonic subsequence. A subsequence of numbers is called bitonic if it is first strictly increasing, then strictly decreasing.Note: Only strictly increasing (no decreasing part) or a strictly decreasing sequence should not be considered as a bitonic sequence.Examples:Input: n = 5, nums[] = [1, 2, 5, 3, 2]Output: 5Explanation: The sequence [1, 2, 5] is increasing and the sequence [3, 2] is decreasing so merging both we will get length 5.Input: n = 8, nums[] = [1, 11, 2, 10, 4, 5, 2, 1]Output: 6Explanation: The bitonic sequence [1, 2, 10, 4, 2, 1] has length 6.Try It YourselfTable of ContentUsing Recursion - O(n*(2^n)) Time and O(n) SpaceUsing Top-Down DP (Memoization) - O(n^2) Time and O(n^2) SpaceUsing Bottom-Up DP (Tabulation) - O(n^2) Time and O(n) SpaceUsing Recursion - O(n*(2^n)) Time and O(n) SpaceIn this approach, we consider every element of the array as a possible peak of a bitonic subsequence. For an element to be a valid peak:The elements on its left must form a strictly increasing subsequence.The elements on its right must form a strictly decreasing subsequence.A sequence that is only increasing or only decreasing does not qualify as bitonic, because a bitonic subsequence must have both parts with a clear turning point (the peak).So, for each index i, we calculate:the longest increasing subsequence ending at i (from the left), andthe longest decreasing subsequence starting from i (to the right).This gives us the bitonic subsequence length with i as the peak.Finally, we take the maximum bitonic length among all choices of peaks.
            C++

    #include <algorithm>
#include <iostream>
#include <vector>
using namespace std;

// Function to find the longest decreasing subsequence
// to the left starting from rightmost element
int leftIncSubs(int prev, int idx, vector<int> &arr)
{
    if (idx < 0)
    {
        return 0;
    }

    int include = 0;
    if (arr[idx] < arr[prev])
    {
        include = 1 + leftIncSubs(idx, idx - 1, arr);
    }

    return max(include, leftIncSubs(prev, idx - 1, arr));
}

// Function to find the longest decreasing subsequence
// to the right starting from leftmost element
int rightDecSubs(int prev, int idx, vector<int> &arr)
{
    if (idx >= arr.size())
    {
        return 0;
    }

    int include = 0;
    if (arr[idx] < arr[prev])
    {
        include = 1 + rightDecSubs(idx, idx + 1, arr);
    }

    return max(include, rightDecSubs(prev, idx + 1, arr));
}

int longestBitonicSequence(int n, vector<int> &nums)
{
    int maxLength = 0;

    // Iterate over potential peaks in the array
    for (int i = 1; i < n - 1; i++)
    {
        int leftLen = leftIncSubs(i, i - 1, nums);
        int rightLen = rightDecSubs(i, i + 1, nums);

        // valid bitonic only if both sides exist
        if (leftLen > 0 && rightLen > 0)
        {
            maxLength = max(maxLength, leftLen + rightLen + 1);
        }
    }
    return maxLength;
}
//Driver Code
int main() {
    vector<int> arr = {12, 11, 40, 5, 3, 1};

    cout << longestBitonicSequence(arr.size(), arr);

    return 0;
}


