    static int longestBitonicSequence(int n, int[] nums) {
        int maxLength = 0;

        // DP tables for memoization
        int[][] leftDp = new int[n][n];
        int[][] rightDp = new int[n][n];

        for (int[] row : leftDp)
            Arrays.fill(row, -1);
        for (int[] row : rightDp)
            Arrays.fill(row, -1);

