        for (int i = 1; i < n - 1; i++) {
            // Longest decreasing subsequence on left of i
            int leftLen = leftIncSubs(i, i - 1, nums, leftDp);

            int rightLen = rightDecSubs(i, i + 1, nums, rightDp);
            if (leftLen > 0 && rightLen > 0)
                maxLength = Math.max(maxLength, leftLen + rightLen + 1);
        }

